css:
/* Check columns: a centred heading, then a row of check marks with a caption under each. */
[data-bz-node="cc-band"] > .bz-container { max-width: calc(min(90vw, 1440px) + 32px); }
[data-bz-section="check-columns"] .bz-block { padding-block: 0; }
[data-bz-section="check-columns"] h2 { margin: 0; text-align: center; font: 700 1.875rem / 1.2 var(--font-heading); color: #000; letter-spacing: 0; }
[data-bz-section="check-columns"] [data-bz-node="cc-row"] { margin-top: 64px; display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); }
[data-bz-section="check-columns"] [data-bz-node="cc-row"] > .bz-col { grid-column: auto; padding-inline: 14px; }
[data-bz-section="check-columns"] .bz-figure { margin: 0; display: flex; justify-content: center; }
[data-bz-section="check-columns"] .bz-figure img { width: auto; max-width: 100%; height: auto; border-radius: 0; }
[data-bz-section="check-columns"] [data-bz-node^="cc-label"] .bz-text p { margin: 28px auto 0; white-space: pre-line; text-align: center; font: 400 0.8rem / 1.65 var(--font-body); color: #333; max-width: 190px; }
[data-bz-section="check-columns"] [data-bz-node^="cc-label"] strong { font-weight: 700; color: #000; }
@media (max-width: 1100px) { [data-bz-section="check-columns"] [data-bz-node="cc-row"] { grid-template-columns: repeat(4, minmax(0, 1fr)); row-gap: 32px; } }
@media (max-width: 640px) { [data-bz-section="check-columns"] [data-bz-node="cc-row"] { grid-template-columns: repeat(2, minmax(0, 1fr)); } [data-bz-section="check-columns"] h2 { font-size: 1.5rem; } }
